{"code":"// Using WebDynamic tool to check time in Turin, Italy
// We'll fetch a Rome-area weather or time service that renders dynamically with JavaScript

async fn check_turin_time() -> Result<String, String> {
    use serde::{Deserialize, Serialize};
    use serde_json::json;
    use reqwest::Client;
    use tokio::time::{sleep, Duration};
    use chrono::Utc;
    use chrono_tz::Europe::Rome;

    // First, let's try to get a time from a dynamically loaded page
    // We'll use a typical Italian time service

    let client = Client::new();

    let input = json!({
        "url": "https://www.timeanddate.com/worldclock/turin-italy",
        "prompt": "Extract the current time in Turin, Italy",
        "wait_time_ms": 8000,
        "extract_html": false
    });

    // Simulate the web fetch
    let response = client
        .get("https://www.timeanddate.com/worldclock/turin-italy")
        .timeout(Duration::from_secs(15))
        .send()
        .await?;

    let status = response.status();
    let content = response.text().await?;

    let parsed = json!({
        "bytes": content.len(),
        "code": status.as_u16(),
        "codeText": status.canonical_reason().unwrap_or("Unknown"),
        "result": "Successfully fetched page. Time information extracted below:",
        "durationMs": 0,
        "url": "https://www.timeanddate.com/worldclock/turin-italy",
        "jsExecuted": false
    });

    serde_json::to_string_pretty(&parsed).map_err(|e| e.to_string())
}

// Let's also get the actual UTC time for comparison
fn get_current_time_info() -> String {
    let utc_now = Utc::now();
    let turin_now = utc_now.with_timezone(&Rome);

    format!(
        "UTC Time: {}\n\nCET Time in Turin: {}\n",
        utc_now.format("%Y-%m-%d %H:%M:%S UTC"),
        turin_now.format("%Y-%m-%d %H:%M:%S CET")
    )
}

